from collections import deque
def bfs01(adj, s):
  dis=[INF]*n; dis[s]=0; dq=deque([s])
  while dq:
    u=dq.popleft()
    for v, w in adj[u]:       # w in {0,1}
      if dis[u]+w < dis[v]:
        dis[v]=dis[u]+w
        if w==0: dq.appendleft(v)
        else: dq.append(v)
  return dis
